// features/lifecycle.feature: "An admin can review vendors"
import { expect, expectStatus, test } from "../../fixtures";

interface QueueItem {
  vendor_id: string;
  vendor_name: string;
}

test.describe("vendor lifecycle: review", () => {
  test("an admin approves a pending extraction and the vendor stays in the queue", { tag: "@LIF-12" }, async ({ apiAs, factory }) => {
    // Arrange
    const { vendor, documents, extractions } = await factory.vendorInReview();
    const admin = await apiAs("admin");

    // Act: open the review queue
    const openQueue = await admin.get("/api/review-queue");
    const queueBefore = await expectStatus<QueueItem[]>(openQueue, 200);
    expect(queueBefore.map((item) => item.vendor_id)).toContain(vendor.id);

    // Act: approve the vendor's w9 extraction
    const decision = await admin.post(`/api/extractions/${extractions.w9.id}/decision`, {
      data: { decision: "approve" },
    });

    // Assert: the decision is accepted and the stored extraction is approved
    await expectStatus(decision, 200);
    expect((await factory.extraction(documents.w9.id, "admin")).status).toBe("approved");

    // Assert: the queue still lists the vendor, which has two extractions left to decide
    const queueAfter = await expectStatus<QueueItem[]>(await admin.get("/api/review-queue"), 200);
    expect(queueAfter.map((item) => item.vendor_id)).toContain(vendor.id);
  });
});
